# 用 select 实现单线程多连接(核心思路)
import select, socket
srv = socket.socket()
srv.bind(("127.0.0.1", 9001)); srv.listen(5)
srv.setblocking(False)
readers = [srv]
while readers:
    r, _, _ = select.select(readers, [], [], 1)
    for s in r:
        if s is srv:
            c, _ = s.accept(); c.setblocking(False)
            readers.append(c)
        else:
            data = s.recv(1024)
            if data: s.sendall(data)
            else: readers.remove(s); s.close()
# 单线程可同时服务于多个连接(状态驱动)

