#!/usr/bin/env python3
import socket
# 服务端: 固定长度头(4字节小端)+消息
def recv_exact(sock, n):
    buf = b""
    while len(buf) < n:
        chunk = sock.recv(n - len(buf))
        if not chunk: raise ConnectionError("closed")
        buf += chunk
    return buf

def recv_msg(sock):
    (ln,) = __import__("struct").unpack(">I", recv_exact(sock, 4))
    return recv_exact(sock, ln)
# 类似地 send_msg 先发长度再发数据

