#!/usr/bin/env python3
# 幂等: 用 Idempotency-Key 防重复提交
import requests, uuid
# 很多支付类 API 支持
idem = str(uuid.uuid4())
h = {"Idempotency-Key": idem}
payload = {"amount": 100, "currency": "usd"}
# 反复提交同一 key 只生效一次
r1 = requests.post("https://httpbin.org/post", json=payload, headers=h, timeout=10)
print("状态:", r1.status_code)

